def transform(grid):
    from collections import Counter

    counts = Counter(val for row in grid for val in row)
    bg_color = counts.most_common(1)[0][0]

    max_count = -1
    block_color = None
    for color, count in counts.items():
        if color != bg_color and count > max_count:
            max_count = count
            block_color = color

    if block_color is None:
        return grid

    min_r, max_r, min_c, max_c = None, None, None, None
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == block_color:
                if min_r is None or r < min_r: min_r = r
                if max_r is None or r > max_r: max_r = r
                if min_c is None or c < min_c: min_c = c
                if max_c is None or c > max_c: max_c = c

    if min_c is None:
        return grid

    output_grid = [row[:] for row in grid]

    global_max_r, global_max_c, global_min_c, global_min_r = max_r, max_c, min_c, min_r

    # First pass: Apply full column projection for all markers
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            marker = grid[r][c]
            if marker == bg_color or marker == block_color:
                continue
            if global_min_c <= c <= global_max_c and global_min_r <= r <= global_max_r:
                for pr in range(min_r, max_r + 1):
                    output_grid[pr][c] = marker

    # Second pass: Apply horizontal projection for outside markers
    for r in range(min_r, max_r + 1):
        row_org = grid[r]

        # Left marker
        left_marker = None
        for c in range(min_c):
            if row_org[c] != bg_color:
                left_marker = row_org[c]
                break
        if left_marker is not None:
            output_grid[r][min_c] = left_marker

        # Right marker
        right_marker = None
        for c in range(max_c + 1, len(row_org)):
            if row_org[c] != bg_color:
                right_marker = row_org[c]
                break
        if right_marker is not None:
            output_grid[r][max_c] = right_marker

    return output_grid
